pm.test("FT-01: Strežnik vrne HTTP 200", function () {
    pm.response.to.have.status(200);
});

pm.test("FT-01: Odgovor je seznam receptov", function () {
    const recepti = pm.response.json();
    pm.expect(recepti).to.be.an("array");
    pm.expect(recepti.length).to.be.above(0);
});

pm.test("FT-01: Recepti imajo zahtevane podatke", function () {
    const recepti = pm.response.json();

    recepti.forEach(function (recept) {
        pm.expect(recept).to.have.property("idRecept");
        pm.expect(recept).to.have.property("naziv");
        pm.expect(recept).to.have.property("steviloOseb");
        pm.expect(recept.steviloOseb).to.be.above(0);
    });
});

pm.test("FT-01: Recept z ID 1 ima pravilno ime", function () {
    const recepti = pm.response.json();
    const recept = recepti.find(r => r.idRecept === 1);

    pm.expect(recept).to.exist;
    pm.expect(recept.naziv).to.eql(
        "Česnove rolice s zeliščnim maslom"
    );
});

pm.test("FT-02: Strežnik vrne HTTP 200", function () {
    pm.response.to.have.status(200);
});

pm.test("FT-02: Vrne pravilen recept po ID", function () {
    const recept = pm.response.json();

    pm.expect(recept.idRecept).to.eql(1);
    pm.expect(recept.naziv).to.eql(
        "Česnove rolice s zeliščnim maslom"
    );
});

pm.test("FT-02: Recept vsebuje zahtevane podatke", function () {
    const recept = pm.response.json();

    pm.expect(recept).to.have.property("idRecept");
    pm.expect(recept).to.have.property("naziv");
    pm.expect(recept).to.have.property("opis");
    pm.expect(recept).to.have.property("sestavine");
    pm.expect(recept).to.have.property("koraki");
});

pm.test("FT-02: Recept vsebuje pravilne sestavine", function () {
    const recept = pm.response.json();

    pm.expect(recept.sestavine).to.be.an("array");
    pm.expect(recept.sestavine).to.have.lengthOf(8);

    pm.expect(recept.sestavine).to.include("500 g Moke");
    pm.expect(recept.sestavine).to.include("250 ml Mleka");
    pm.expect(recept.sestavine).to.include("4 stroki Česna");
});

pm.test("FT-02: Recept vsebuje korake priprave", function () {
    const recept = pm.response.json();

    pm.expect(recept.koraki).to.be.an("array");
    pm.expect(recept.koraki.length).to.be.above(0);

    recept.koraki.forEach(function (korak) {
        pm.expect(korak).to.be.a("string");
        pm.expect(korak.trim()).to.not.be.empty;
    });
});

pm.test("FT-02: Recept ima veljaven opis", function () {
    const recept = pm.response.json();

    pm.expect(recept.opis).to.be.a("string");
    pm.expect(recept.opis.length).to.be.above(20);
});

pm.test("FT-03: Streznik vrne HTTP 200", function () {
    pm.response.to.have.status(200);
});

pm.test("FT-03: Odgovor vsebuje nakupovalni seznam", function () {
    const podatki = pm.response.json();

    pm.expect(podatki).to.have.property("shoppingList");
    pm.expect(podatki.shoppingList).to.be.an("object");
});

pm.test("FT-03: Seznam vsebuje vseh 8 sestavin", function () {
    const seznam = pm.response.json().shoppingList;

    pm.expect(Object.keys(seznam)).to.have.lengthOf(8);
});

pm.test("FT-03: Seznam vsebuje zahtevane sestavine", function () {
    const seznam = pm.response.json().shoppingList;

    pm.expect(seznam).to.have.property("Mleka");
    pm.expect(seznam).to.have.property("Moke");
    pm.expect(seznam).to.have.property("Masla");
    pm.expect(seznam).to.have.property("Česna");
});

pm.test("FT-03: Kolicine ustrezajo trenutni implementaciji", function () {
    const seznam = pm.response.json().shoppingList;

    pm.expect(seznam["Mleka"]).to.eql(500);
    pm.expect(seznam["Moke"]).to.eql(1000);
    pm.expect(seznam["Masla"]).to.eql(100);
    pm.expect(seznam["Česna"]).to.eql(8);
});

pm.test("FT-03: Vse kolicine so pozitivne", function () {
    const seznam = pm.response.json().shoppingList;

    Object.values(seznam).forEach(function (kolicina) {
        pm.expect(kolicina).to.be.a("number");
        pm.expect(kolicina).to.be.above(0);
    });
});
